screenPanels.initJs:
function(container, apiUrl, tables) {
  const ROWS_PER_PAGE = 10;
  let allRows = [];
  let currentPage = 1;
  let filteredRows = [];

  // テーブルインデックスの決定（営業活動テーブルを使用）
  const tableIndex = 0;

  // 1. 再描画関数
  function renderRows(rows) {
    filteredRows = rows;
    currentPage = 1;
    renderPage();
  }

  function renderPage() {
    const tbody = container.querySelector("#results-tbody");
    const startIdx = (currentPage - 1) * ROWS_PER_PAGE;
    const endIdx = startIdx + ROWS_PER_PAGE;
    const pageRows = filteredRows.slice(startIdx, endIdx);

    const totalPages = Math.ceil(filteredRows.length / ROWS_PER_PAGE);
    container.querySelector("[data-testid='current-page']").textContent = currentPage;
    container.querySelector("[data-testid='total-pages']").textContent = totalPages || 1;
    container.querySelector("[data-testid='result-count']").textContent = filteredRows.length;

    if (pageRows.length === 0) {
      tbody.innerHTML = '<tr style="height: 2rem;"><td colspan="7" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当するデータがありません</td></tr>';
      return;
    }

    tbody.innerHTML = pageRows.map(r => {
      const activityDate = r.活動日 ? new Date(r.活動日).toLocaleDateString('ja-JP') : '—';
      const userName = r.ユーザーID ? (allRows.find(row => row.id === r.ユーザーID)?.氏名 || '—') : '—';
      const amount = r.成果金額 ? `¥${Number(r.成果金額).toLocaleString()}` : '—';
      const status = r.成果有無 ? '成約' : '未成約';

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); hover:background: rgba(255,255,255,0.04);">
        <td style="padding: 0.75rem;">${activityDate}</td>
        <td style="padding: 0.75rem;">${r.顧客名 || '—'}</td>
        <td style="padding: 0.75rem;">${r.案件名 || '—'}</td>
        <td style="padding: 0.75rem;">${r.活動種別 || '—'}</td>
        <td style="padding: 0.75rem; text-align: right;">${amount}</td>
        <td style="padding: 0.75rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500; background: ${r.成果有無 ? 'rgba(34,197,94,0.2)' : 'rgba(107,114,128,0.2)'}; color: ${r.成果有無 ? '#86efac' : '#d1d5db'};">
            ${status}
          </span>
        </td>
        <td style="padding: 0.75rem; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.id}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">詳細</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込み
  if (tables && tables[0] && tables[0].records) {
    allRows = tables[0].records;
    renderRows(allRows);
  }

  // 3. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const startDate = container.querySelector("[data-testid='start-date-input']").value;
    const endDate = container.querySelector("[data-testid='end-date-input']").value;
    const userId = container.querySelector("[data-testid='user-select']").value;
    const customerName = container.querySelector("[data-testid='customer-name-input']").value.toLowerCase();
    const status = container.querySelector("[data-testid='status-filter']").value;
    const metric = container.querySelector("[data-testid='metric-select']").value;

    const rows = await window.aivicApi.list(tableIndex);
    if (!rows) return;

    allRows = rows;
    let filtered = rows;

    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(r => new Date(r.活動日 || 0) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filtered = filtered.filter(r => new Date(r.活動日 || 0) <= end);
    }
    if (userId) {
      filtered = filtered.filter(r => r.ユーザーID === userId);
    }
    if (customerName) {
      filtered = filtered.filter(r => (r.顧客名 || '').toLowerCase().includes(customerName));
    }
    if (status === '成約') {
      filtered = filtered.filter(r => r.成果有無 === true);
    } else if (status === '未成約') {
      filtered = filtered.filter(r => r.成果有無 === false);
    }

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='start-date-input']").value = '';
    container.querySelector("[data-testid='end-date-input']").value = '';
    container.querySelector("[data-testid='user-select']").value = '';
    container.querySelector("[data-testid='customer-name-input']").value = '';
    container.querySelector("[data-testid='status-filter']").value = '';
    container.querySelector("[data-testid='metric-select']").value = '';
    renderRows(allRows);
  });

  // 5. ページネーション
  container.querySelector("[data-testid='prev-page-button']").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderPage();
    }
  });

  container.querySelector("[data-testid='next-page-button']").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredRows.length / ROWS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderPage();
    }
  });

  // 6. CSVエクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ['活動日', '営業担当者', '顧客名', '案件名', '活動種別', '成果金額', '成約ステータス'];
    const csvContent = [
      '\uFEFF' + headers.map(h => `"${h}"`).join(','),
      ...rows.map(r => {
        const activityDate = r.活動日 ? new Date(r.活動日).toLocaleDateString('ja-JP') : '';
        const amount = r.成果金額 || '';
        const status = r.成果有無 ? '成約' : '未成約';
        return [
          `"${activityDate}"`,
          `"${r.顧客名 || ''}"`,
          `"${r.案件名 || ''}"`,
          `"${r.活動種別 || ''}"`,
          `"${amount}"`,
          `"${status}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `営業データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.id === id);
      if (row) {
        alert(`詳細情報:\n活動日: ${row.活動日}\n顧客名: ${row.顧客名}\n案件名: ${row.案件名}\n活動内容: ${row.活動内容 || '—'}`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テンプレート、期間、配信先、スケジュール設定を管理
  const templateSelect = container.querySelector('#template-select');
  const periodStart = container.querySelector('#period-start');
  const periodEnd = container.querySelector('#period-end');
  const emailRecipients = container.querySelector('#email-recipients');
  const autoDeliveryEnable = container.querySelector('#auto-delivery-enable');
  const scheduleSettings = container.querySelector('#schedule-settings');
  const deliveryFrequency = container.querySelector('#delivery-frequency');
  const dayTimeSettings = container.querySelector('#day-time-settings');
  const deliveryDay = container.querySelector('#delivery-day');
  const deliveryTime = container.querySelector('#delivery-time');
  const includeKpi = container.querySelector('#include-kpi');
  const includeActivity = container.querySelector('#include-activity');
  const includeDeal = container.querySelector('#include-deal');
  const previewContent = container.querySelector('#preview-content');
  const deliveryHistory = container.querySelector('#delivery-history');
  const btnGenerate = container.querySelector('#btn-generate');
  const btnSchedule = container.querySelector('#btn-schedule');
  const btnViewGenerated = container.querySelector('#btn-view-generated');

  // 初期日付設定（今月の開始日と本日）
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  periodStart.valueAsDate = firstDay;
  periodEnd.valueAsDate = today;

  // 自動配信スケジュール設定の表示/非表示
  autoDeliveryEnable.addEventListener('change', (e) => {
    scheduleSettings.style.display = e.target.checked ? 'block' : 'none';
  });

  // 配信頻度に応じて曜日設定の表示/非表示
  deliveryFrequency.addEventListener('change', (e) => {
    dayTimeSettings.style.display = (e.target.value === 'weekly') ? 'block' : 'none';
  });

  // プレビュー更新関数
  function updatePreview() {
    const template = templateSelect.value;
    const start = periodStart.value;
    const end = periodEnd.value;
    const hasKpi = includeKpi.checked;
    const hasActivity = includeActivity.checked;
    const hasDeal = includeDeal.checked;

    if (!template || !start || !end) {
      previewContent.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px;">テンプレートと期間を選択するとプレビューが表示されます</div>';
      return;
    }

    let preview = `<div style="border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 12px; margin-bottom: 12px;">
      <div style="font-weight: 600; margin-bottom: 4px;">営業成果レポート</div>
      <div style="color: var(--text-muted); font-size: 12px;">期間: ${start} ～ ${end}</div>
    </div>`;

    if (hasKpi) {
      preview += `<div style="margin-bottom: 12px;">
        <div style="font-weight: 600; margin-bottom: 6px; color: var(--primary);">成果指標</div>
        <div style="font-size: 12px; line-height: 1.8;">
          • 売上高: ¥2,450,000 (目標比 98%)<br/>
          • 受注件数: 12件 (目標比 100%)<br/>
          • 顧客満足度: 4.2/5.0
        </div>
      </div>`;
    }

    if (hasActivity) {
      preview += `<div style="margin-bottom: 12px;">
        <div style="font-weight: 600; margin-bottom: 6px; color: var(--primary);">営業活動</div>
        <div style="font-size: 12px; line-height: 1.8;">
          • 訪問: 24件<br/>
          • 電話: 18件<br/>
          • メール: 32件<br/>
          • 提案: 8件
        </div>
      </div>`;
    }

    if (hasDeal) {
      preview += `<div style="margin-bottom: 12px;">
        <div style="font-weight: 600; margin-bottom: 6px; color: var(--primary);">成約実績</div>
        <div style="font-size: 12px; line-height: 1.8;">
          • 成約件数: 12件<br/>
          • 成約金額: ¥2,450,000<br/>
          • 平均契約金額: ¥204,167
        </div>
      </div>`;
    }

    previewContent.innerHTML = preview;
  }

  // 各設定変更時にプレビュー更新
  templateSelect.addEventListener('change', updatePreview);
  periodStart.addEventListener('change', updatePreview);
  periodEnd.addEventListener('change', updatePreview);
  includeKpi.addEventListener('change', updatePreview);
  includeActivity.addEventListener('change', updatePreview);
  includeDeal.addEventListener('change', updatePreview);

  // 生成ボタン
  btnGenerate.addEventListener('click', async () => {
    const template = templateSelect.value;
    const start = periodStart.value;
    const end = periodEnd.value;

    if (!template || !start || !end) {
      alert('テンプレート、期間を選択してください');
      return;
    }

    const reportData = {
      templateId: template,
      periodStart: start,
      periodEnd: end,
      includeKpi: includeKpi.checked,
      includeActivity: includeActivity.checked,
      includeDeal: includeDeal.checked,
      recipients: emailRecipients.value.split(',').map(e => e.trim()).filter(e => e)
    };

    const saved = await window.aivicApi.save(5, reportData); // テーブルインデックス 5: 生成済みレポート
    if (saved) {
      alert('レポートを生成しました');
      // 配信履歴を更新
      const history = `<div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.1); font-size: 12px;">
        <div style="font-weight: 500;">生成: ${new Date().toLocaleString('ja-JP')}</div>
        <div style="color: var(--text-muted); font-size: 11px;">テンプレート: ${template}</div>
      </div>` + deliveryHistory.innerHTML;
      deliveryHistory.innerHTML = history;
    }
  });

  // スケジュール保存ボタン
  btnSchedule.addEventListener('click', async () => {
    if (!autoDeliveryEnable.checked) {
      alert('自動配信を有効にしてください');
      return;
    }

    const frequency = deliveryFrequency.value;
    const time = deliveryTime.value;

    if (!frequency || !time) {
      alert('配信頻度と時刻を設定してください');
      return;
    }

    const scheduleData = {
      templateId: templateSelect.value,
      frequency: frequency,
      dayOfWeek: frequency === 'weekly' ? deliveryDay.value : null,
      time: time,
      recipients: emailRecipients.value.split(',').map(e => e.trim()).filter(e => e),
      enabled: true
    };

    const saved = await window.aivicApi.save(4, scheduleData); // テーブルインデックス 4: レポートテンプレート
    if (saved) {
      alert('スケジュールを保存しました');
    }
  });

  // 生成済みレポート確認ボタン
  btnViewGenerated.addEventListener('click', () => {
    window.showScreen('scr-1781941234200');
  });

  // 初期プレビュー表示
  updatePreview();
}

function(container, apiUrl, tables) {
  const reportTbody = container.querySelector("#report-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const emptyState = container.querySelector("#empty-state");
  let selectedReportId = null;

  // 1. テーブル再描画関数
  function renderReportList(rows) {
    reportTbody.innerHTML = rows.map(r => {
      const statusClass = r.配信ステータス === "配信済み" ? "delivered" : r.配信ステータス === "配信失敗" ? "failed" : "pending";
      const statusLabel = r.配信ステータス || "未配信";
      return `
        <tr data-id="${r.レポートID}" class="report-row" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.04); transition: background 0.2s;">
          <td style="padding: 8px; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.レポートタイトル || "-"}</td>
          <td style="padding: 8px; text-align: center; font-size: 11px; font-weight: 600;">
            <span style="display: inline-block; padding: 3px 6px; border-radius: 2px; background: ${statusClass === "delivered" ? "rgba(76,175,80,0.2); color: #4caf50;" : statusClass === "failed" ? "rgba(244,67,54,0.2); color: #f44336;" : "rgba(255,152,0,0.2); color: #ff9800;"}">${statusLabel}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll(".report-row").forEach(row => {
      row.addEventListener("click", () => {
        selectedReportId = row.dataset.id;
        container.querySelectorAll(".report-row").forEach(r => r.style.background = "");
        row.style.background = "rgba(255,255,255,0.05)";
        showDetail(rows.find(r => r.レポートID === selectedReportId));
      });
    });
  }

  // 2. 詳細表示関数
  function showDetail(report) {
    if (!report) return;

    emptyState.style.display = "none";
    detailPanel.style.display = "block";

    container.querySelector("#detail-title").textContent = report.レポートタイトル || "-";
    container.querySelector("#detail-generated").textContent = report.生成日時 ? new Date(report.生成日時).toLocaleString("ja-JP") : "-";
    container.querySelector("#detail-status").textContent = report.配信ステータス || "-";
    container.querySelector("#detail-template").textContent = report.テンプレートID || "-";
    container.querySelector("#detail-user").textContent = report.ユーザーID || "-";
    container.querySelector("#detail-email").textContent = report.配信先メールアドレス || "-";
    container.querySelector("#detail-delivered").textContent = report.配信日時 ? new Date(report.配信日時).toLocaleString("ja-JP") : "未配信";

    // サマリー
    container.querySelector("#summary-contracts").textContent = report.成約件数 || 0;
    container.querySelector("#summary-activities").textContent = report.営業活動件数 || 0;
    const revenue = report.成約金額 || 0;
    container.querySelector("#summary-revenue").textContent = "¥" + revenue.toLocaleString("ja-JP");

    // 達成率（仮計算: 成約件数 / 営業活動件数 * 100）
    const rate = report.営業活動件数 > 0 ? Math.round((report.成約件数 / report.営業活動件数) * 100) : 0;
    container.querySelector("#achievement-rate").textContent = rate + "%";

    // レポート内容
    container.querySelector("#detail-content").textContent = report.レポート内容 || "内容なし";

    // 配信履歴（簡易表示）
    const historyHtml = report.配信日時 
      ? `<div style="padding: 8px; background: rgba(76,175,80,0.1); border-radius: 3px; border-left: 3px solid #4caf50;">
           <div style="font-weight: 600; color: var(--text);">配信済み</div>
           <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${new Date(report.配信日時).toLocaleString("ja-JP")}</div>
         </div>`
      : `<div style="padding: 8px; background: rgba(255,152,0,0.1); border-radius: 3px; border-left: 3px solid #ff9800;">
           <div style="font-weight: 600; color: var(--text);">未配信</div>
           <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">配信待機中</div>
         </div>`;
    container.querySelector("#delivery-history").innerHTML = historyHtml;
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows && rows.length > 0) {
      renderReportList(rows);
    }
  });

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    window.aivicApi.list(0).then(rows => {
      const filtered = rows.filter(r => 
        (r.レポートタイトル || "").toLowerCase().includes(keyword) ||
        (r.配信ステータス || "").toLowerCase().includes(keyword)
      );
      renderReportList(filtered);
    });
  });

  // 5. 再配信ボタン
  container.querySelector("#btn-resend").addEventListener("click", async () => {
    if (!selectedReportId) {
      alert("レポートを選択してください");
      return;
    }
    if (!confirm("このレポートを再配信しますか？")) return;

    const updated = await window.aivicApi.update(0, selectedReportId, { 
      配信ステータス: "配信済み",
      配信日時: new Date().toISOString()
    });
    if (updated) {
      alert("再配信しました");
      window.aivicApi.list(0).then(rows => {
        renderReportList(rows);
        showDetail(rows.find(r => r.レポートID === selectedReportId));
      });
    }
  });

  // 6. ダウンロードボタン
  container.querySelector("#btn-download").addEventListener("click", () => {
    if (!selectedReportId) {
      alert("レポートを選択してください");
      return;
    }
    window.aivicApi.list(0).then(rows => {
      const report = rows.find(r => r.レポートID === selectedReportId);
      if (!report) return;

      const csv = "レポートタイトル,生成日時,配信ステータス,成約件数,営業活動件数,売上金額\n" +
        `"${report.レポートタイトル || ""}","${report.生成日時 || ""}","${report.配信ステータス || ""}",${report.成約件数 || 0},${report.営業活動件数 || 0},${report.成約金額 || 0}`;

      const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `report_${selectedReportId}.csv`;
      link.click();
    });
  });

  // 7. 削除ボタン
  container.querySelector("#btn-delete").addEventListener("click", async () => {
    if (!selectedReportId) {
      alert("レポートを選択してください");
      return;
    }
    if (!confirm("このレポートを削除しますか？")) return;

    await window.aivicApi.delete(0, selectedReportId);
    alert("削除しました");
    selectedReportId = null;
    detailPanel.style.display = "none";
    emptyState.style.display = "flex";
    window.aivicApi.list(0).then(rows => renderReportList(rows));
  });
}

function(container, apiUrl, tables) {
  // ===== 1. グラフ描画関数 =====
  function drawRevenueChart() {
    const canvas = container.querySelector('#chart-revenue-trend');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
    const data = [3200, 3500, 3100, 4200, 4100, 4500, 4800, 4300, 4600, 4900, 5100, 4375];
    const maxVal = Math.max(...data);
    const padding = 20;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / data.length;

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';

    data.forEach((val, i) => {
      const barHeight = (val / maxVal) * chartHeight;
      const x = padding + i * barWidth + barWidth / 2 - 8;
      const y = canvas.height - padding - barHeight;
      ctx.fillStyle = '#4a90e2';
      ctx.fillRect(x, y, 16, barHeight);
    });

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '9px sans-serif';
    months.forEach((m, i) => {
      ctx.fillText(m, padding + i * barWidth + barWidth / 2, canvas.height - padding + 4);
    });
  }

  function drawActivityBreakdown() {
    const canvas = container.querySelector('#chart-activity-breakdown');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const activities = [
      { label: '訪問', value: 65, color: '#4a90e2' },
      { label: '電話', value: 45, color: '#7b68ee' },
      { label: 'メール', value: 30, color: '#50c878' },
      { label: '提案', value: 16, color: '#ffa500' }
    ];
    const total = activities.reduce((sum, a) => sum + a.value, 0);
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) / 2 - 10;

    let startAngle = -Math.PI / 2;
    activities.forEach(activity => {
      const sliceAngle = (activity.value / total) * 2 * Math.PI;
      ctx.fillStyle = activity.color;
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.lineTo(centerX, centerY);
      ctx.fill();
      startAngle += sliceAngle;
    });

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'left';
    activities.forEach((activity, i) => {
      ctx.fillStyle = activity.color;
      ctx.fillRect(8, 8 + i * 14, 8, 8);
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(`${activity.label} (${activity.value})`, 20, 8 + i * 14);
    });
  }

  function drawDealRateTrend() {
    const canvas = container.querySelector('#chart-deal-rate-trend');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
    const rates = [12, 14, 11, 16, 15, 18, 19, 17, 18, 19, 20, 15];
    const padding = 20;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const pointSpacing = chartWidth / (rates.length - 1);

    ctx.strokeStyle = '#4a90e2';
    ctx.lineWidth = 2;
    ctx.beginPath();
    rates.forEach((rate, i) => {
      const x = padding + i * pointSpacing;
      const y = canvas.height - padding - (rate / 25) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    ctx.fillStyle = '#4a90e2';
    rates.forEach((rate, i) => {
      const x = padding + i * pointSpacing;
      const y = canvas.height - padding - (rate / 25) * chartHeight;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '9px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((m, i) => {
      ctx.fillText(m, padding + i * pointSpacing, canvas.height - padding + 10);
    });
  }

  // ===== 2. フィルター適用 =====
  container.querySelector('[data-testid="filter-apply-button"]').addEventListener('click', () => {
    const period = container.querySelector('[data-testid="period-select"]').value;
    const salesperson = container.querySelector('[data-testid="salesperson-select"]').value;
    const category = container.querySelector('[data-testid="category-select"]').value;
    console.log('フィルター適用:', { period, salesperson, category });
    // ここでダッシュボードデータを再取得・再描画
    drawRevenueChart();
    drawActivityBreakdown();
    drawDealRateTrend();
  });

  // ===== 3. 詳細表示ボタン =====
  container.querySelector('[data-testid="view-details-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781941234200');
  });

  // ===== 4. テンプレート管理ボタン =====
  container.querySelector('[data-testid="manage-templates-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781941196452');
  });

  // ===== 5. 生成済みレポートボタン =====
  container.querySelector('[data-testid="view-reports-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781941234200');
  });

  // ===== 6. CSVエクスポート =====
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', () => {
    const headers = ['指標', '実績', '目標', '達成率'];
    const data = [
      ['売上高', '¥4,375万', '¥5,000万', '87.5%'],
      ['成約件数', '23件', '26件', '88.5%'],
      ['営業活動件数', '156件', '150件', '104%'],
      ['平均契約金額', '¥190万', '¥170万', '111.8%']
    ];

    const csv = '\uFEFF' + headers.join(',') + '\n' + data.map(row => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv; charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'dashboard-export.csv';
    link.click();
  });

  // ===== 7. 初期グラフ描画 =====
  setTimeout(() => {
    drawRevenueChart();
    drawActivityBreakdown();
    drawDealRateTrend();
  }, 100);
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 初期化 & 状態管理
  // ============================================
  const state = {
    periodStart: null,
    periodEnd: null,
    salesUser: null,
    customerFilter: null,
    template: null,
    metrics: { revenue: true, contracts: true, activities: true },
    deliveryEmail: null,
    deliverySchedule: 'immediate',
    scheduleDateTime: null,
  };

  // テーブルデータ（初期値）
  const salesActivities = tables[0]?.records || [];
  const contracts = tables[1]?.records || [];
  const customers = tables[2]?.records || [];

  // ============================================
  // 2. ユーティリティ関数
  // ============================================
  function formatCurrency(amount) {
    return '¥' + (amount || 0).toLocaleString('ja-JP');
  }

  function calculateMetrics() {
    let filteredActivities = salesActivities;
    let filteredContracts = contracts;

    // 期間フィルタ
    if (state.periodStart && state.periodEnd) {
      const start = new Date(state.periodStart);
      const end = new Date(state.periodEnd);
      filteredActivities = filteredActivities.filter(a => {
        const d = new Date(a.活動日 || a.activityDate);
        return d >= start && d <= end;
      });
      filteredContracts = filteredContracts.filter(c => {
        const d = new Date(c.成約日 || c.contractDate);
        return d >= start && d <= end;
      });
    }

    // 営業担当者フィルタ
    if (state.salesUser) {
      filteredActivities = filteredActivities.filter(a => a.ユーザーID === state.salesUser || a.userId === state.salesUser);
      filteredContracts = filteredContracts.filter(c => c.ユーザーID === state.salesUser || c.userId === state.salesUser);
    }

    // 顧客ステータスフィルタ
    if (state.customerFilter) {
      const statusMap = {
        'status-prospect': '見込み客',
        'status-existing': '既存顧客',
        'status-inactive': '休止中',
      };
      const targetStatus = statusMap[state.customerFilter];
      const filteredCustomerIds = customers
        .filter(c => (c.ステータス || c.status) === targetStatus)
        .map(c => c.顧客企業ID || c.customerId);
      filteredContracts = filteredContracts.filter(c => 
        filteredCustomerIds.includes(c.顧客企業ID || c.customerId)
      );
    }

    // 集計
    const totalRevenue = filteredContracts.reduce((sum, c) => sum + (c.成約金額 || c.contractAmount || 0), 0);
    const contractCount = filteredContracts.length;
    const activityCount = filteredActivities.length;

    return { totalRevenue, contractCount, activityCount };
  }

  function buildCustomerResults() {
    let filteredContracts = contracts;

    if (state.periodStart && state.periodEnd) {
      const start = new Date(state.periodStart);
      const end = new Date(state.periodEnd);
      filteredContracts = filteredContracts.filter(c => {
        const d = new Date(c.成約日 || c.contractDate);
        return d >= start && d <= end;
      });
    }

    if (state.salesUser) {
      filteredContracts = filteredContracts.filter(c => c.ユーザーID === state.salesUser || c.userId === state.salesUser);
    }

    // 顧客別に集計
    const customerMap = {};
    filteredContracts.forEach(c => {
      const custId = c.顧客企業ID || c.customerId;
      const custName = c.顧客名 || c.customerName || '不明';
      if (!customerMap[custId]) {
        customerMap[custId] = { name: custName, revenue: 0, count: 0 };
      }
      customerMap[custId].revenue += c.成約金額 || c.contractAmount || 0;
      customerMap[custId].count += 1;
    });

    return Object.values(customerMap).sort((a, b) => b.revenue - a.revenue);
  }

  function updatePreview() {
    const metrics = calculateMetrics();
    const customerResults = buildCustomerResults();

    // 集計結果表示
    if (state.metrics.revenue) {
      container.querySelector('#preview-revenue').textContent = formatCurrency(metrics.totalRevenue);
    }
    if (state.metrics.contracts) {
      container.querySelector('#preview-contracts').textContent = metrics.contractCount + '件';
    }
    if (state.metrics.activities) {
      container.querySelector('#preview-activities').textContent = metrics.activityCount + '件';
    }

    // 期間表示
    if (state.periodStart && state.periodEnd) {
      container.querySelector('#preview-period').textContent = 
        state.periodStart + ' ～ ' + state.periodEnd;
    }

    // 顧客別成果テーブル
    const tbody = container.querySelector('#preview-customer-tbody');
    if (customerResults.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td style="padding: 6px 4px; color: var(--text-muted);">データなし</td><td style="padding: 6px 4px; color: var(--text-muted); text-align: right;">-</td><td style="padding: 6px 4px; color: var(--text-muted); text-align: right;">-</td></tr>';
    } else {
      tbody.innerHTML = customerResults.map(cr => `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 4px; color: var(--text);">${cr.name}</td>
          <td style="padding: 6px 4px; color: var(--text); text-align: right;">${formatCurrency(cr.revenue)}</td>
          <td style="padding: 6px 4px; color: var(--text); text-align: right;">${cr.count}件</td>
        </tr>
      `).join('');
    }
  }

  // ============================================
  // 3. イベントリスナー登録
  // ============================================

  // 期間選択
  container.querySelector('#period-start').addEventListener('change', (e) => {
    state.periodStart = e.target.value;
    updatePreview();
  });
  container.querySelector('#period-end').addEventListener('change', (e) => {
    state.periodEnd = e.target.value;
    updatePreview();
  });

  // 営業担当者選択
  container.querySelector('#sales-user').addEventListener('change', (e) => {
    state.salesUser = e.target.value || null;
    updatePreview();
  });

  // 顧客フィルタ
  container.querySelector('#customer-filter').addEventListener('change', (e) => {
    state.customerFilter = e.target.value || null;
    updatePreview();
  });

  // テンプレート選択
  container.querySelector('#template-select').addEventListener('change', (e) => {
    state.template = e.target.value || null;
  });

  // 成果指標チェックボックス
  container.querySelector('#metric-revenue').addEventListener('change', (e) => {
    state.metrics.revenue = e.target.checked;
    updatePreview();
  });
  container.querySelector('#metric-contracts').addEventListener('change', (e) => {
    state.metrics.contracts = e.target.checked;
    updatePreview();
  });
  container.querySelector('#metric-activities').addEventListener('change', (e) => {
    state.metrics.activities = e.target.checked;
    updatePreview();
  });

  // 配信先メール
  container.querySelector('#delivery-email').addEventListener('change', (e) => {
    state.deliveryEmail = e.target.value;
  });

  // 配信スケジュール
  container.querySelector('#delivery-schedule').addEventListener('change', (e) => {
    state.deliverySchedule = e.target.value;
    const scheduleContainer = container.querySelector('#schedule-datetime-container');
    if (e.target.value === 'scheduled') {
      scheduleContainer.style.display = 'block';
    } else {
      scheduleContainer.style.display = 'none';
    }
  });

  // スケジュール日時
  container.querySelector('#schedule-datetime').addEventListener('change', (e) => {
    state.scheduleDateTime = e.target.value;
  });

  // プレビュー確認ボタン
  container.querySelector('#btn-preview').addEventListener('click', () => {
    updatePreview();
    alert('プレビューを更新しました。');
  });

  // レポート生成・配信ボタン
  container.querySelector('#btn-generate').addEventListener('click', async () => {
    if (!state.deliveryEmail) {
      alert('配信先メールアドレスを入力してください。');
      return;
    }

    if (state.deliverySchedule === 'scheduled' && !state.scheduleDateTime) {
      alert('配信日時を指定してください。');
      return;
    }

    const metrics = calculateMetrics();
    const reportData = {
      templateId: state.template || 'default',
      periodStart: state.periodStart,
      periodEnd: state.periodEnd,
      salesUserId: state.salesUser,
      customerFilter: state.customerFilter,
      metrics: state.metrics,
      totalRevenue: metrics.totalRevenue,
      contractCount: metrics.contractCount,
      activityCount: metrics.activityCount,
      deliveryEmail: state.deliveryEmail,
      deliverySchedule: state.deliverySchedule,
      scheduleDateTime: state.scheduleDateTime,
      generatedAt: new Date().toISOString(),
    };

    // API で保存（生成済みレポート）
    const saved = await window.aivicApi.save(5, reportData); // テーブルインデックス 5 = 生成済みレポート
    if (saved) {
      alert('レポートを生成・配信しました。');
      // 配信履歴も記録
      await window.aivicApi.save(6, {
        generatedReportId: saved.id,
        deliveryEmail: state.deliveryEmail,
        deliveryStatus: state.deliverySchedule === 'immediate' ? '配信済み' : '予約待ち',
        deliveryDateTime: state.deliverySchedule === 'immediate' ? new Date().toISOString() : state.scheduleDateTime,
      });
    }
  });

  // ============================================
  // 4. 初期表示
  // ============================================
  updatePreview();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const GENERATED_REPORTS_IDX = 0;
  const DELIVERY_HISTORY_IDX = 1;

  // 初期データ
  let generatedReports = tables[GENERATED_REPORTS_IDX]?.records || [];
  let deliveryHistory = tables[DELIVERY_HISTORY_IDX]?.records || [];

  // DOM要素
  const selectReport = container.querySelector('#select-report');
  const selectRecipients = container.querySelector('#select-recipients');
  const selectScheduleType = container.querySelector('#select-schedule-type');
  const inputReportSearch = container.querySelector('#input-report-search');
  const inputEmailSubject = container.querySelector('#input-email-subject');
  const inputDeliveryDatetime = container.querySelector('#input-delivery-datetime');
  const textareaMessage = container.querySelector('#textarea-message');
  const btnDeliver = container.querySelector('#btn-deliver');
  const btnCancel = container.querySelector('#btn-cancel');
  const reportInfo = container.querySelector('#report-info');
  const previewContainer = container.querySelector('#preview-container');
  const historyTbody = container.querySelector('#history-tbody');
  const inputHistorySearch = container.querySelector('#input-history-search');
  const confirmDialog = container.querySelector('#confirm-dialog');
  const confirmMessage = container.querySelector('#confirm-message');
  const btnConfirmOk = container.querySelector('#btn-confirm-ok');
  const btnConfirmCancel = container.querySelector('#btn-confirm-cancel');
  const successMessage = container.querySelector('#success-message');
  const scheduledOptions = container.querySelector('#scheduled-options');
  const recipientCount = container.querySelector('#recipient-count');

  // 配信履歴の再描画
  function renderHistory(rows) {
    if (rows.length === 0) {
      historyTbody.innerHTML = '<tr><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">配信履歴がありません</td></tr>';
      return;
    }
    historyTbody.innerHTML = rows.map(r => {
      const statusColor = r.配信ステータス === '成功' ? '#4caf50' : r.配信ステータス === '失敗' ? '#f44336' : '#ff9800';
      const openedBadge = r.開封フラグ ? '✓' : '-';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 8px; color: var(--text);">${r.配信先メールアドレス || '-'}</td>
          <td style="padding: 6px 8px; color: var(--text-muted);">${r.配信日時 ? new Date(r.配信日時).toLocaleString('ja-JP') : '-'}</td>
          <td style="padding: 6px 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 2px; font-size: 10px; font-weight: 600;">${r.配信ステータス || '-'}</span>
          </td>
          <td style="padding: 6px 8px; text-align: center; color: var(--text-muted);">${openedBadge}</td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ表示
  renderHistory(deliveryHistory);

  // レポート選択時の処理
  selectReport.addEventListener('change', (e) => {
    const reportId = e.target.value;
    if (!reportId) {
      reportInfo.style.display = 'none';
      previewContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted);">レポートを選択してプレビューを表示</div>';
      return;
    }

    const report = generatedReports.find(r => r.id === reportId || r.レポートID === reportId);
    if (report) {
      reportInfo.style.display = 'block';
      container.querySelector('#report-period').textContent = 
        `${new Date(report.レポート期間開始日).toLocaleDateString('ja-JP')} ～ ${new Date(report.レポート期間終了日).toLocaleDateString('ja-JP')}`;
      container.querySelector('#report-deals').textContent = report.成約件数 || 0;
      container.querySelector('#report-activities').textContent = report.営業活動件数 || 0;

      // プレビュー表示
      previewContainer.innerHTML = `
        <div style="margin-bottom: 8px;">
          <strong style="color: var(--text);">${report.レポートタイトル || 'レポート'}</strong>
        </div>
        <div style="white-space: pre-wrap; word-break: break-word; max-height: 150px; overflow-y: auto;">
          ${report.レポート内容 || '（内容なし）'}
        </div>
      `;
    }
  });

  // 配信スケジュール切り替え
  selectScheduleType.addEventListener('change', (e) => {
    scheduledOptions.style.display = e.target.value === 'scheduled' ? 'block' : 'none';
  });

  // 配信対象の選択数更新
  selectRecipients.addEventListener('change', () => {
    const selected = Array.from(selectRecipients.selectedOptions).length;
    recipientCount.textContent = selected;
  });

  // 配信履歴検索
  inputHistorySearch.addEventListener('input', (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = deliveryHistory.filter(r => 
      (r.配信先メールアドレス || '').toLowerCase().includes(keyword)
    );
    renderHistory(filtered);
  });

  // 配信実行
  btnDeliver.addEventListener('click', () => {
    const reportId = selectReport.value;
    const recipients = Array.from(selectRecipients.selectedOptions).map(o => o.textContent);
    const method = document.querySelector('input[name="delivery-method"]:checked').value;
    const scheduleType = selectScheduleType.value;

    if (!reportId) {
      alert('レポートを選択してください');
      return;
    }
    if (recipients.length === 0) {
      alert('配信対象を選択してください');
      return;
    }

    const report = generatedReports.find(r => r.id === reportId || r.レポートID === reportId);
    const confirmText = `
レポート: ${report?.レポートタイトル || 'レポート'}
配信先: ${recipients.join(', ')}
配信方法: ${method === 'email' ? 'メール' : 'システム内通知'}
配信タイプ: ${scheduleType === 'immediate' ? '即座に配信' : `予約配信（${inputDeliveryDatetime.value}）`}

この内容で配信してもよろしいですか？
    `;

    confirmMessage.textContent = confirmText;
    confirmDialog.removeAttribute('hidden');
  });

  // 配信確認キャンセル
  btnConfirmCancel.addEventListener('click', () => {
    confirmDialog.setAttribute('hidden', '');
  });

  // 配信確認OK
  btnConfirmOk.addEventListener('click', async () => {
    confirmDialog.setAttribute('hidden', '');

    const reportId = selectReport.value;
    const recipientIds = Array.from(selectRecipients.selectedOptions).map(o => o.value);
    const method = document.querySelector('input[name="delivery-method"]:checked').value;
    const scheduleType = selectScheduleType.value;
    const subject = inputEmailSubject.value || '営業成果レポート';
    const message = textareaMessage.value;

    const report = generatedReports.find(r => r.id === reportId || r.レポートID === reportId);

    // 配信履歴に追加（シミュレーション）
    const newDeliveries = recipientIds.map(userId => ({
      id: `delivery-${Date.now()}-${Math.random()}`,
      生成済みレポートID: reportId,
      配信先ユーザーID: userId,
      配信先メールアドレス: selectRecipients.querySelector(`option[value="${userId}"]`)?.textContent.match(/\(([^)]+)\)/)?.[1] || '',
      配信日時: new Date().toISOString(),
      配信ステータス: '成功',
      配信方法: method,
      開封フラグ: false,
      再配信フラグ: false,
      再配信回数: 0
    }));

    // API保存（複数件）
    for (const delivery of newDeliveries) {
      await window.aivicApi.save(DELIVERY_HISTORY_IDX, delivery);
    }

    // 履歴を再読み込み
    const updated = await window.aivicApi.list(DELIVERY_HISTORY_IDX);
    if (updated) {
      deliveryHistory = updated;
      renderHistory(deliveryHistory);
    }

    // 成功メッセージ表示
    successMessage.removeAttribute('hidden');
    setTimeout(() => {
      successMessage.setAttribute('hidden', '');
    }, 3000);

    // フォームリセット
    selectReport.value = '';
    selectRecipients.value = '';
    inputEmailSubject.value = '';
    textareaMessage.value = '';
    reportInfo.style.display = 'none';
    previewContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted);">レポートを選択してプレビューを表示</div>';
    recipientCount.textContent = '0';
  });

  // キャンセルボタン
  btnCancel.addEventListener('click', () => {
    selectReport.value = '';
    selectRecipients.value = '';
    inputEmailSubject.value = '';
    textareaMessage.value = '';
    reportInfo.style.display = 'none';
    previewContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted);">レポートを選択してプレビューを表示</div>';
    recipientCount.textContent = '0';
  });
}

