  const kpiRevenue = container.querySelector("#kpi-revenue");
  const kpiAvgRevenue = container.querySelector("#kpi-avg-revenue");
  const kpiActivities = container.querySelector("#kpi-activities");

  // ===== 2. 初期状態設定 =====
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  startDateInput.valueAsDate = firstDay;
  endDateInput.valueAsDate = today;

  // ===== 3. リセット処理 =====
  btnReset.addEventListener("click", () => {
    startDateInput.valueAsDate = firstDay;
    endDateInput.valueAsDate = today;
    userSelect.value = "";
    customerSelect.value = "";
    Object.values(metricCheckboxes).forEach(cb => cb.checked = true);
    progressSection.style.display = "none";
    resultSection.style.display = "none";
    emptySection.style.display = "flex";
    btnNext.style.display = "none";
  });

  // ===== 4. 集計実行処理 =====
  btnExecute.addEventListener("click", async () => {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const userId = userSelect.value;
    const customerId = customerSelect.value;

    if (!startDate || !endDate) {
      alert("集計期間を指定してください");
      return;
    }

    // 進捗表示開始
    emptySection.style.display = "none";
    resultSection.style.display = "none";
    progressSection.style.display = "block";
    btnNext.style.display = "none";

    // シミュレーション: 進捗アニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.floor(progress) + "%";
      if (progress >= 100) clearInterval(progressInterval);
    }, 300);

    // API から営業活動と成約データを取得
    try {
      const activities = await window.aivicApi.list(1); // 営業活動テーブル
      const contracts = await window.aivicApi.list(3);   // 成約テーブル

      // フィルタリング
      const filteredActivities = (activities || []).filter(a => {
        const actDate = new Date(a.活動日);
        const inRange = actDate >= new Date(startDate) && actDate <= new Date(endDate);
        const userMatch = !userId || a.ユーザーID === userId;
        return inRange && userMatch;
      });

      const filteredContracts = (contracts || []).filter(c => {
        const contDate = new Date(c.成約日);
        const inRange = contDate >= new Date(startDate) && contDate <= new Date(endDate);
        const userMatch = !userId || c.ユーザーID === userId;
        return inRange && userMatch;
      });

      // 指標計算
      const contractCount = filteredContracts.length;
      const totalRevenue = filteredContracts.reduce((sum, c) => sum + (c.成約金額 || 0), 0);
      const avgRevenue = contractCount > 0 ? Math.round(totalRevenue / contractCount) : 0;
      const activityCount = filteredActivities.length;

      // 結果表示
      setTimeout(() => {
        progressSection.style.display = "none";
        resultSection.style.display = "block";
        emptySection.style.display = "none";
        btnNext.style.display = "block";

        // KPI 更新
        kpiContracts.textContent = contractCount;
        kpiRevenue.textContent = "¥" + totalRevenue.toLocaleString();
        kpiAvgRevenue.textContent = "¥" + avgRevenue.toLocaleString();
        kpiActivities.textContent = activityCount;

        // 詳細テーブル更新
        const resultRows = [];
        if (metricCheckboxes.contracts.checked) {
          resultRows.push({ name: "成約件数", value: contractCount });
        }
        if (metricCheckboxes.revenue.checked) {
          resultRows.push({ name: "成約金額合計", value: "¥" + totalRevenue.toLocaleString() });
        }
        if (metricCheckboxes.avgRevenue.checked) {
          resultRows.push({ name: "平均成約金額", value: "¥" + avgRevenue.toLocaleString() });
        }
        if (metricCheckboxes.activities.checked) {
          resultRows.push({ name: "営業活動件数", value: activityCount });
        }

        resultTbody.innerHTML = resultRows.map(r => `
          <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
            <td style="padding: 0.5rem; color: var(--text);">${r.name}</td>
            <td style="padding: 0.5rem; text-align: right; color: var(--text); font-weight: 600;">${r.value}</td>
          </tr>
        `).join("");
      }, 1500);
    } catch (err) {
      console.error("集計エラー:", err);
      progressSection.style.display = "none";
      resultSection.style.display = "block";
      alert("集計処理中にエラーが発生しました");
    }
  });

  // ===== 5. 次へボタン =====
  btnNext.addEventListener("click", () => {
    window.showScreen("scr-1781941221780"); // レポート自動生成・配信画面へ
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const contractsTableIdx = tables.findIndex(t => t.tableName === '成約');
  const activitiesTableIdx = tables.findIndex(t => t.tableName === '営業活動');
  const metricsTableIdx = tables.findIndex(t => t.tableName === '成果指標');
  const customersTableIdx = tables.findIndex(t => t.tableName === '顧客企業');
  const usersTableIdx = tables.findIndex(t => t.tableName === 'ユーザー');

  // 初期データ
  let contractsData = (contractsTableIdx >= 0 && tables[contractsTableIdx].records) || [];
  let activitiesData = (activitiesTableIdx >= 0 && tables[activitiesTableIdx].records) || [];
  let customersData = (customersTableIdx >= 0 && tables[customersTableIdx].records) || [];
  let usersData = (usersTableIdx >= 0 && tables[usersTableIdx].records) || [];

  // プレビューテーブル再描画
  function renderPreviewTable(rows) {
    const tbody = container.querySelector('#preview-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.8125rem;">該当データがありません</td></tr>';
      return;
    }
    tbody.innerHTML = rows.slice(0, 10).map(r => {
      const contractDate = r['成約日'] ? new Date(r['成約日']).toLocaleDateString('ja-JP') : '-';
      const customerName = r['顧客企業ID'] ? (customersData.find(c => c['顧客企業ID'] === r['顧客企業ID'])?.[' 企業名'] || '-') : '-';
      const salesperson = r['ユーザーID'] ? (usersData.find(u => u['ユーザーID'] === r['ユーザーID'])?.[' 氏名'] || '-') : '-';
      const amount = r['成約金額'] ? `¥${Number(r['成約金額']).toLocaleString()}` : '¥0';
      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 0.5rem; color: var(--text);">${contractDate}</td>
        <td style="padding: 0.5rem; color: var(--text);">${customerName}</td>
        <td style="padding: 0.5rem; color: var(--text);">${salesperson}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--primary); font-weight: 500;">${amount}</td>
      </tr>`;
    }).join('');
  }

  // プレビュー集計更新
  function updatePreviewSummary(rows) {
    const activitiesCount = activitiesData.length;
    const contractsCount = rows.length;
    const revenueTotal = rows.reduce((sum, r) => sum + (Number(r['成約金額']) || 0), 0);
    const revenueAvg = contractsCount > 0 ? Math.round(revenueTotal / contractsCount) : 0;

    container.querySelector('#preview-activities-count').textContent = activitiesCount;
    container.querySelector('#preview-contracts-count').textContent = contractsCount;
    container.querySelector('#preview-revenue-total').textContent = `¥${revenueTotal.toLocaleString()}`;
    container.querySelector('#preview-revenue-avg').textContent = `¥${revenueAvg.toLocaleString()}`;
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const customerFilter = container.querySelector('#customer-filter').value;
    const salespersonFilter = container.querySelector('#salesperson-filter').value;

    let filtered = contractsData;

    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(r => new Date(r['成約日']) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filtered = filtered.filter(r => new Date(r['成約日']) <= end);
    }
    if (customerFilter) {
      filtered = filtered.filter(r => r['顧客企業ID'] === customerFilter);
    }
    if (salespersonFilter) {
      filtered = filtered.filter(r => r['ユーザーID'] === salespersonFilter);
    }

    return filtered;
  }

  // 初期プレビュー表示
  renderPreviewTable(contractsData.slice(0, 10));
  updatePreviewSummary(contractsData);

  // 更新ボタン
  container.querySelector('#refresh-preview').addEventListener('click', () => {
    const filtered = applyFilters();
    renderPreviewTable(filtered);
    updatePreviewSummary(filtered);
  });

  // レポート生成ボタン
  container.querySelector('#btn-generate').addEventListener('click', async () => {
    const templateId = container.querySelector('#template-select').value;
    if (!templateId) {
      alert('テンプレートを選択してください');
      return;
    }

    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const includeActivities = container.querySelector('#include-activities').checked;
    const includeContracts = container.querySelector('#include-contracts').checked;
    const includeMetrics = container.querySelector('#include-metrics').checked;

    const filtered = applyFilters();
    const reportData = {
      templateId,
      startDate,
      endDate,
      includeActivities,
      includeContracts,
      includeMetrics,
      contractsCount: filtered.length,
      revenueTotal: filtered.reduce((sum, r) => sum + (Number(r['成約金額']) || 0), 0),
      generatedAt: new Date().toISOString()
    };

    // 生成済みレポート情報を保持
    const reportEl = container.querySelector('#generated-report');
    reportEl.dataset.reportId = 'report-' + Date.now();
    reportEl.dataset.content = JSON.stringify(reportData);

    alert(`レポートを生成しました。\n件数: ${filtered.length}件\n金額: ¥${reportData.revenueTotal.toLocaleString()}`);
  });

  // フォーマット変換ボタン
  container.querySelector('#btn-convert').addEventListener('click', () => {
    const reportEl = container.querySelector('#generated-report');
    if (!reportEl.dataset.reportId) {
      alert('先にレポートを生成してください');
      return;
    }

    const format = container.querySelector('input[name="format"]:checked').value;
    reportEl.dataset.format = format;
    alert(`フォーマットを ${format.toUpperCase()} に変換しました`);
  });

  // ダウンロードボタン
  container.querySelector('#btn-download').addEventListener('click', () => {
    const reportEl = container.querySelector('#generated-report');
    if (!reportEl.dataset.reportId) {
      alert('先にレポートを生成してください');
      return;
    }

    const format = container.querySelector('input[name="format"]:checked').value;
    const reportData = JSON.parse(reportEl.dataset.content || '{}');
    const filename = `report-${reportEl.dataset.reportId}.${format === 'excel' ? 'xlsx' : format}`;

    if (format === 'csv') {
      const csv = 'レポートID,テンプレートID,期間開始,期間終了,成約件数,売上合計\n' +
        `${reportEl.dataset.reportId},${reportData.templateId},${reportData.startDate},${reportData.endDate},${reportData.contractsCount},${reportData.revenueTotal}`;
      const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = filename;
      link.click();
    } else {
      // PDF/Excel は簡易実装（実際にはライブラリが必要）
      const content = `レポートID: ${reportEl.dataset.reportId}\nテンプレート: ${reportData.templateId}\n期間: ${reportData.startDate} ～ ${reportData.endDate}\n成約件数: ${reportData.contractsCount}\n売上合計: ¥${reportData.revenueTotal}`;
      const blob = new Blob([content], { type: 'text/plain;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = filename.replace(/\.(xlsx|pdf)$/, '.txt');
      link.click();
    }

    alert(`${filename} をダウンロードしました`);
  });

  // 日付変更時にプレビュー自動更新
  container.querySelector('#start-date').addEventListener('change', () => {
    const filtered = applyFilters();
    renderPreviewTable(filtered);
    updatePreviewSummary(filtered);
  });
  container.querySelector('#end-date').addEventListener('change', () => {
    const filtered = applyFilters();
    renderPreviewTable(filtered);
    updatePreviewSummary(filtered);
  });
  container.querySelector('#customer-filter').addEventListener('change', () => {
    const filtered = applyFilters();
    renderPreviewTable(filtered);
    updatePreviewSummary(filtered);
  });
  container.querySelector('#salesperson-filter').addEventListener('change', () => {
    const filtered = applyFilters();
    renderPreviewTable(filtered);
    updatePreviewSummary(filtered);
  });
}

function(container, apiUrl, tables) {
  const reportTbody = container.querySelector("#report-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const emptyState = container.querySelector("#empty-state");
  const filterType = container.querySelector("#filter-report-type");
  const filterStatus = container.querySelector("#filter-status");
  const searchInput = container.querySelector("#input-search");
  const btnSearch = container.querySelector("#btn-search");
  const btnExport = container.querySelector("#btn-export");
  const btnSend = container.querySelector("#btn-send");
  const btnResend = container.querySelector("#btn-resend");
  const btnCloseDetail = container.querySelector("#btn-close-detail");

  let allReports = [];
  let selectedReportId = null;

  // 1. 再描画関数
  function renderReportList(reports) {
    reportTbody.innerHTML = reports.map(r => {
      const statusColor = r.配信ステータス === "配信済み" ? "rgba(100,200,100,0.2)" : 
                          r.配信ステータス === "配信失敗" ? "rgba(200,100,100,0.2)" : "rgba(150,150,150,0.2)";
      const statusText = r.配信ステータス || "未配信";
      const periodStart = r.レポート期間開始日 ? new Date(r.レポート期間開始日).toLocaleDateString('ja-JP') : "-";
      const periodEnd = r.レポート期間終了日 ? new Date(r.レポート期間終了日).toLocaleDateString('ja-JP') : "-";
      const generatedDate = r.生成日時 ? new Date(r.生成日時).toLocaleDateString('ja-JP') : "-";

      return `<tr data-id="${r.id}" class="report-row" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.04); hover: background: rgba(255,255,255,0.02);">
        <td style="padding: 10px 12px; color: var(--text);">${r.レポートタイトル || "-"}</td>
        <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px;">${periodStart}〜${periodEnd}</td>
        <td style="padding: 10px 12px;">
          <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${statusColor}; color: var(--text); font-size: 11px; font-weight: 500;">${statusText}</span>
        </td>
        <td style="padding: 10px 12px; text-align: center; color: var(--text-muted); font-size: 12px;">${generatedDate}</td>
      </tr>`;
    }).join("");
  }

  // 詳細パネル表示関数
  function showDetail(reportId) {
    const report = allReports.find(r => r.id === reportId);
    if (!report) return;

    selectedReportId = reportId;

    // タイトル・期間・生成日
    container.querySelector("#detail-title").textContent = report.レポートタイトル || "（タイトルなし）";
    const periodStart = report.レポート期間開始日 ? new Date(report.レポート期間開始日).toLocaleDateString('ja-JP') : "-";
    const periodEnd = report.レポート期間終了日 ? new Date(report.レポート期間終了日).toLocaleDateString('ja-JP') : "-";
    container.querySelector("#detail-period").textContent = `期間: ${periodStart} 〜 ${periodEnd}`;
    const generatedDate = report.生成日時 ? new Date(report.生成日時).toLocaleString('ja-JP') : "-";
    container.querySelector("#detail-generated").textContent = `生成日時: ${generatedDate}`;

    // KPI
    container.querySelector("#kpi-contracts").textContent = (report.成約件数 || 0).toString();
    container.querySelector("#kpi-revenue").textContent = `¥${(report.成約金額 || 0).toLocaleString()}`;
    container.querySelector("#kpi-activities").textContent = (report.営業活動件数 || 0).toString();

    // 顧客別成果表（ダミー）
    const customerTbody = container.querySelector("#customer-tbody");
    customerTbody.innerHTML = `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
        <td style="padding: 8px 10px; color: var(--text);">サンプル企業A</td>
        <td style="padding: 8px 10px; text-align: right; color: var(--text);">2</td>
        <td style="padding: 8px 10px; text-align: right; color: var(--text);">¥500,000</td>
      </tr>
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.04);">
        <td style="padding: 8px 10px; color: var(--text);">サンプル企業B</td>
        <td style="padding: 8px 10px; text-align: right; color: var(--text);">1</td>
        <td style="padding: 8px 10px; text-align: right; color: var(--text);">¥300,000</td>
      </tr>
    `;

    // 営業活動履歴（タイムライン）
    const timeline = container.querySelector("#activity-timeline");
    timeline.innerHTML = `
      <div style="padding: 10px 0; border-left: 2px solid var(--primary); padding-left: 12px; margin-left: 6px;">
        <div style="margin-bottom: 12px;">
          <p style="margin: 0 0 2px 0; font-size: 12px; font-weight: 500; color: var(--text);">訪問</p>
          <p style="margin: 0; font-size: 11px; color: var(--text-muted);">2024-01-15 - サンプル企業A訪問</p>
        </div>
        <div style="margin-bottom: 12px;">
          <p style="margin: 0 0 2px 0; font-size: 12px; font-weight: 500; color: var(--text);">提案</p>
          <p style="margin: 0; font-size: 11px; color: var(--text-muted);">2024-01-18 - 提案資料提出</p>
        </div>
        <div>
          <p style="margin: 0 0 2px 0; font-size: 12px; font-weight: 500; color: var(--text);">成約</p>
          <p style="margin: 0; font-size: 11px; color: var(--text-muted);">2024-01-20 - 契約締結</p>
        </div>
      </div>
    `;

    // 配信ボタン表示切り替え
    const isDelivered = report.配信ステータス === "配信済み";
    btnSend.style.display = isDelivered ? "none" : "block";
    btnResend.style.display = isDelivered ? "block" : "none";

    // パネル表示
    emptyState.style.display = "none";
    detailPanel.style.display = "block";
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allReports = rows || tables[0].records || [];
    renderReportList(allReports);
  });

  // 3. 検索・フィルタ
  function applyFilters() {
    let filtered = allReports;

    const typeVal = filterType.value;
    if (typeVal) {
      filtered = filtered.filter(r => r.レポート種別 === typeVal);
    }

    const statusVal = filterStatus.value;
    if (statusVal) {
      filtered = filtered.filter(r => (r.配信ステータス || "未配信") === statusVal);
    }

    const searchVal = searchInput.value.toLowerCase();
    if (searchVal) {
      filtered = filtered.filter(r => 
        (r.レポートタイトル || "").toLowerCase().includes(searchVal)
      );
    }

    renderReportList(filtered);
  }

  filterType.addEventListener("change", applyFilters);
  filterStatus.addEventListener("change", applyFilters);
  btnSearch.addEventListener("click", applyFilters);
  searchInput.addEventListener("keypress", e => {
    if (e.key === "Enter") applyFilters();
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const row = e.target.closest(".report-row");
    if (row) {
      const reportId = row.dataset.id;
      showDetail(reportId);
    }
  });

  // 5. 配信ボタン
  btnSend.addEventListener("click", async () => {
    if (!selectedReportId) return;
    if (!confirm("このレポートを配信しますか？")) return;

    const report = allReports.find(r => r.id === selectedReportId);
    if (report) {
      const updated = await window.aivicApi.update(0, selectedReportId, {
        配信ステータス: "配信済み",
        配信日時: new Date().toISOString()
      });
      if (updated) {
        allReports = allReports.map(r => r.id === selectedReportId ? { ...r, 配信ステータス: "配信済み", 配信日時: new Date().toISOString() } : r);
        renderReportList(allReports);
        showDetail(selectedReportId);
        alert("レポートを配信しました");
      }
    }
  });

  btnResend.addEventListener("click", async () => {
    if (!selectedReportId) return;
    if (!confirm("このレポートを再配信しますか？")) return;

    const report = allReports.find(r => r.id === selectedReportId);
    if (report) {
      const updated = await window.aivicApi.update(0, selectedReportId, {
        配信日時: new Date().toISOString()
      });
      if (updated) {
        alert("レポートを再配信しました");
      }
    }
  });

  // 6. 詳細パネル閉じる
  btnCloseDetail.addEventListener("click", () => {
    detailPanel.style.display = "none";
    emptyState.style.display = "flex";
    selectedReportId = null;
  });

  // 7. CSV出力
  btnExport.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0) || allReports;
    if (!rows || rows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["レポートID", "レポートタイトル", "期間開始", "期間終了", "生成日時", "配信ステータス", "成約件数", "売上金額"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.id || "",
        `"${(r.レポートタイトル || "").replace(/"/g, '""')}"`,
        r.レポート期間開始日 ? new Date(r.レポート期間開始日).toLocaleDateString('ja-JP') : "",
        r.レポート期間終了日 ? new Date(r.レポート期間終了日).toLocaleDateString('ja-JP') : "",
        r.生成日時 ? new Date(r.生成日時).toLocaleString('ja-JP') : "",
        r.配信ステータス || "未配信",
        r.成約件数 || 0,
        r.成約金額 || 0
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `reports_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // プレビュー更新関数
  function updatePreview() {
    const templateSelect = container.querySelector('#template-select');
    const periodStart = container.querySelector('[data-testid="period-start"]');
    const periodEnd = container.querySelector('[data-testid="period-end"]');
    const recipientSelect = container.querySelector('[data-testid="recipient-select"]');
    const scheduleFreq = container.querySelector('[data-testid="schedule-frequency"]');
    const scheduleTime = container.querySelector('[data-testid="schedule-time"]');
    const formatRadios = container.querySelectorAll('input[name="format"]');
    const metricCheckboxes = container.querySelectorAll('input[type="checkbox"][data-testid^="metric-"]');

    // テンプレート名
    const templateText = templateSelect.options[templateSelect.selectedIndex]?.text || '未選択';
    container.querySelector('#preview-template').textContent = templateText;

    // 期間
    const periodText = periodStart.value && periodEnd.value 
      ? `${periodStart.value} ～ ${periodEnd.value}`
      : '未設定';
    container.querySelector('#preview-period').textContent = periodText;

    // 配信先
    const selectedRecipients = Array.from(recipientSelect.selectedOptions).map(o => o.text).join(', ') || '未選択';
    container.querySelector('#preview-recipients').textContent = selectedRecipients;

    // スケジュール
    const freqText = scheduleFreq.options[scheduleFreq.selectedIndex]?.text || '未設定';
    const scheduleText = scheduleFreq.value ? `${freqText} ${scheduleTime.value}` : '未設定';
    container.querySelector('#preview-schedule').textContent = scheduleText;

    // 形式
    const selectedFormat = Array.from(formatRadios).find(r => r.checked)?.value || 'html';
    const formatMap = { html: 'HTML', pdf: 'PDF', excel: 'Excel' };
    container.querySelector('#preview-format').textContent = formatMap[selectedFormat];

    // 選択指標の表示
    const selectedMetrics = Array.from(metricCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => {
        const labels = { revenue: '売上高', contracts: '成約件数', activities: '営業活動件数', conversion: '成約率' };
        return labels[cb.value];
      });

    const metricsTable = container.querySelector('[data-testid="preview-metrics"]');
    if (metricsTable) {
      metricsTable.innerHTML = selectedMetrics.length > 0
        ? selectedMetrics.map(m => `<tr style="border-bottom: 1px solid rgba(255,255,255,0.1);"><td style="padding: 0.4rem; color: var(--text-muted);">${m}</td><td style="padding: 0.4rem; text-align: right; color: var(--text);">-</td></tr>`).join('')
        : '<tr><td colspan="2" style="padding: 0.4rem; color: var(--text-muted);">指標を選択してください</td></tr>';
    }
  }

  // イベントリスナー登録
  const inputs = container.querySelectorAll('select, input[type="date"], input[type="time"], input[type="checkbox"], input[type="radio"]');
  inputs.forEach(input => {
    input.addEventListener('change', updatePreview);
  });

  // プレビュー更新ボタン
  container.querySelector('[data-testid="refresh-preview"]').addEventListener('click', updatePreview);

  // キャンセルボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (confirm('処理をキャンセルしますか？')) {
      window.showScreen('scr-1781941234200');
    }
  });

  // 生成・配信実行ボタン
  container.querySelector('[data-testid="execute-button"]').addEventListener('click', async () => {
    const templateSelect = container.querySelector('#template-select');
    const periodStart = container.querySelector('[data-testid="period-start"]');
    const periodEnd = container.querySelector('[data-testid="period-end"]');
    const recipientSelect = container.querySelector('[data-testid="recipient-select"]');
    const scheduleFreq = container.querySelector('[data-testid="schedule-frequency"]');
    const scheduleTime = container.querySelector('[data-testid="schedule-time"]');

    // バリデーション
    if (!templateSelect.value) {
      alert('テンプレートを選択してください');
      return;
    }
    if (!periodStart.value || !periodEnd.value) {
      alert('生成対象期間を指定してください');
      return;
    }
    if (recipientSelect.selectedOptions.length === 0) {
      alert('配信先ユーザーを選択してください');
      return;
    }
    if (!scheduleFreq.value) {
      alert('配信スケジュールを設定してください');
      return;
    }

    // 実行確認
    if (!confirm('レポートを生成・配信実行しますか？')) {
      return;
    }

    // 生成済みレポートテーブルにレコード追加（シミュレーション）
    const reportData = {
      template_id: templateSelect.value,
      period_start: periodStart.value,
      period_end: periodEnd.value,
      recipients: Array.from(recipientSelect.selectedOptions).map(o => o.value).join(','),
      schedule_frequency: scheduleFreq.value,
      schedule_time: scheduleTime.value,
      status: 'pending'
    };

    const saved = await window.aivicApi.save(6, reportData);
    if (saved) {
      alert('レポート生成・配信処理を開始しました。\n配信状況は「生成済みレポート確認画面」でご確認ください。');
      window.showScreen('scr-1781941234200');
    }
  });

  // 初期プレビュー更新
  updatePreview();
}
